golden = {"휴가 규정?":"HR-12", "법인카드 한도?":"FIN-03", "VPN 접속?":"IT-07", "출장비 정산?":"FIN-09"}
retrieved = {"휴가 규정?":["HR-12","HR-02","HR-30"], "법인카드 한도?":["FIN-01","FIN-03","HR-12"],
             "VPN 접속?":["IT-02","IT-11","IT-01"], "출장비 정산?":["FIN-09","FIN-03","FIN-01"]}
